import { createContext, useContext, useState, useEffect, useMemo, useCallback, memo } from 'react';

// Context for global XP (Lesson 9)
const AppContext = createContext();
function useXP() { return useContext(AppContext); }

// Custom hook (Lesson 9)
function useLocalStorage(key, initial) {
 const [val, setVal] = useState(() => JSON.parse(localStorage.getItem(key) || JSON.stringify(initial)));
 useEffect(() => localStorage.setItem(key, JSON.stringify(val)), [key, val]);
 return [val, setVal];
}

// Memoized card with dynamic styling (Lesson 8 + 7 + 4)
const LessonCard = memo(function Card({ id, title, status, onComplete }) {
 const badge = { completed: {c: '#4ade80', t: 'COMPLETED'}, current: {c: '#61dafb', t: 'CURRENT'}, locked: {c: '#94a3b8', t: 'LOCKED'}}[status];
 return (
 <div style={{background: 'rgba(15,31,51,0.88)', backdropFilter: 'blur(18px)', border: `1px solid ${badge.c}30`, borderRadius: '20px', padding: '20px'}}>
 <div style={{display: 'flex', justifyContent: 'space-between'}}>
 <span style={{color: '#61dafb', fontSize: '11px'}}>LESSON {String(id).padStart(2,'0')}</span>
 <span style={{color: badge.c, background: badge.c+'20', padding: '5px 8px', borderRadius: '999px', fontSize: '10px'}}>{badge.t}</span>
 </div>
 <h3 style={{color: 'white'}}>{title}</h3>
 {status!=='locked' && <button onClick={() => onComplete(id)} style={{background: '#61dafb', border: 'none', padding: '8px 12px', borderRadius: '8px', marginTop: '10px', fontWeight: '700'}}>Start →</button>}
 </div>
 );
});

function App() {
 const [lessons, setLessons] = useLocalStorage("lessons", [
 {id: 1, title: "Introduction to React", status: "completed"},
 {id: 2, title: "JSX and Components", status: "current"},
 {id: 3, title: "Props", status: "locked"},
 ]);
 const [xp, setXp] = useLocalStorage("xp", 120);
 const [search, setSearch] = useState(""); // Local state (not global)
 const [filter, setFilter] = useState("all");

 const filtered = useMemo(() => lessons.filter(l => {
 const matchSearch = l.title.toLowerCase().includes(search.toLowerCase());
 const matchFilter = filter==='all' || l.status===filter;
 return matchSearch && matchFilter;
 }), [lessons, search, filter]); // useMemo for performance

 const handleComplete = useCallback((id) => {
 setLessons(prev => prev.map(l => l.id===id? {...l, status: 'completed'} : l.id===id+1? {...l, status: 'current'} : l));
 setXp(prev => prev + 50);
 }, [setLessons, setXp]); // useCallback stable reference for memo

 const completed = useMemo(() => lessons.filter(l => l.status==='completed').length, [lessons]);
 const progress = (completed / lessons.length) * 100;

 return (
 <AppContext.Provider value={{ xp }}>
 <div style={{background: '#07111f', minHeight: '100vh', padding: '20px', color: 'white'}}>
 <div style={{display: 'flex', gap: '10px'}}><span>⚡ {xp} XP</span><span>{completed}/{lessons.length} {Math.round(progress)}%</span></div>
 <div style={{height: '9px', background: 'rgba(148,163,184,0.12)', borderRadius: '99px', margin: '15px 0'}}><div style={{width: `${progress}%`, height: '100%', background: 'linear-gradient(90deg, #61dafb, #8b5cf6)', borderRadius: '99px', transition: 'width 0.6s ease'}}></div></div>
 <div style={{display: 'flex', gap: '10px', marginBottom: '15px'}}>
 <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search..." style={{padding: '8px', flex: 1}} />
 <select value={filter} onChange={(e) => setFilter(e.target.value)} style={{padding: '8px'}}><option value="all">All</option><option value="completed">Completed</option><option value="current">Current</option></select>
 </div>
 {filtered.length===0? <p>No lessons match "{search}" <button onClick={() => {setSearch(""); setFilter("all");}}>Clear</button></p> : <div style={{display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '16px'}}>{filtered.map(l => <LessonCard key={l.id} {...l} onComplete={handleComplete} />)}</div>}
 </div>
 </AppContext.Provider>
 );
}
export default App;
